'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'factory returns a function', function test( t ) {
	var q = factory( 1.0 );
	t.strictEqual( typeof q, 'function', 'returns expected value' );
	t.end();
});

tape( 'if sigma is NaN or sigma < 0, returned function always returns NaN', function test( t ) {
	var q;

	q = factory( NaN );
	t.ok( isnan( q( 0.5 ) ), 'returns expected value' );

	q = factory( -1.0 );
	t.ok( isnan( q( 0.5 ) ), 'returns expected value' );

	t.end();
});

tape( 'if sigma = 0, quantile always returns 0', function test( t ) {
	var q = factory( 0.0 );
	t.strictEqual( q( 0.0 ), 0.0, 'returns expected value' );
	t.strictEqual( q( 0.5 ), 0.0, 'returns expected value' );
	t.strictEqual( q( 1.0 ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'if p < 0, p > 1, or p is NaN, quantile returns NaN', function test( t ) {
	var q = factory( 1.0 );

	t.ok( isnan( q( -0.1 ) ), 'returns expected value' );
	t.ok( isnan( q( 1.1 ) ), 'returns expected value' );
	t.ok( isnan( q( NaN ) ), 'returns expected value' );

	t.end();
});

tape( 'if p = 1, the function returns positive infinity', function test( t ) {
	var q = factory( 1.0 );
	t.strictEqual( q( 1.0 ), PINF, 'returns expected value' );
	t.end();
});

tape( 'the factory evaluates the half-normal quantile', function test( t ) {
	var expected;
	var sigma;
	var y;
	var q;
	var i;
	var p;

	p = data.p;
	sigma = data.sigma;
	expected = data.expected;
	for ( i = 0; i < p.length; i++ ) {
		q = factory( sigma[i] );
		if ( expected[i] !== null ) {
			y = q( p[i] );
			t.strictEqual( isAlmostSameValue( y, expected[ i ], 40.0 ), true, 'within tolerance. p: '+p[ i ]+'. sigma: '+sigma[ i ]+'. y: '+y+'. expected: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
